import itertools
def boxdiag(seeds,H,W):
    P=[[0]*W for _ in range(H)]
    for s in seeds: P[s[0]][s[1]]=1
    for a,b in itertools.combinations(seeds,2):
        (x1,y1),(x2,y2)=a,b
        L=max(y1,y2)-min(y1,y2)
        for c in range(L+1):
            if x1<=x2:
                for dx in [-1,1]:
                    i,j=x1+dx*c,y1+dx*c
                    P[i][j]=1
            else:
                for dx in [-1,1]:
                    i,j=x2+dx*c,y2+dx*c
                    P[i][j]=1
    return P
